<div class="alert alert-info">Los permisos definen exactamente qué puede ver y administrar cada tipo de usuario. El superadministrador siempre conserva acceso total.</div><div class="role-grid"><?php foreach($roles as $role):?><form class="card role-card" method="post" action="<?= url('administracion/roles/'.$role['id']) ?>"><?= csrf_field() ?><div class="card-header"><div><h2><?= e($role['name']) ?></h2><p><?= e($role['description']) ?></p></div><span class="badge bg-secondary"><?= e($role['slug']) ?></span></div><div class="card-body permission-list"><?php $last='';foreach($permissions as $permission):?><?php if($last!==$permission['module']):$last=$permission['module'];?><h3><?= e(ucfirst($last)) ?></h3><?php endif;?><label class="form-check"><input type="checkbox" class="form-check-input" name="permissions[]" value="<?= $permission['id'] ?>" <?= in_array((int)$permission['id'],$map[$role['id']]??[],true)||$role['slug']==='superadmin'?'checked':'' ?> <?= $role['slug']==='superadmin'?'disabled':'' ?>><span><?= e($permission['name']) ?></span></label><?php endforeach;?></div><?php if($role['slug']!=='superadmin'):?><div class="card-footer"><button class="btn btn-primary w-100">Guardar permisos</button></div><?php endif;?></form><?php endforeach;?></div>
